import test from 'node:test';
import assert from 'node:assert/strict';
import { builtinCatalog, instantiateCatalog, generatePreset, inspectComponent, componentPreview, editPlane, normalizeTransform, transformPlane, transformPoint, rad, dot, norm, sub, clone, cubeSolid, prismSolid, cutSolid, geometryStats, signedVolume, uniquePoints, instancePlanes, machineReport, interfaceReport, sectionSegments } from '../src/index.js';
import { lSolid, ringSolid, disconnectedSolid, halfPlane } from './fixtures.mjs';
const near = (a, b, e = 1e-7) => assert.ok(Math.abs(a - b) < e, `${a} != ${b}`);
for (const entry of builtinCatalog())
    test(`default recipe ${entry.id}: ${entry.name}`, () => { const c = instantiateCatalog(entry), r = inspectComponent(c); assert.ok(Number.isFinite(r.stats.volume) && r.stats.volume > 0); assert.equal(r.stats.active, c.planes.length); assert.equal(r.stats.inactive.length, 0); assert.ok(r.polys.every(f => f.v.every(v => v.every(Number.isFinite)))); assert.equal(c.planes.some(p => p.role === 'interface'), false); });
test('library counts and identity', () => { const c = builtinCatalog(); assert.equal(c.length, 70); assert.equal(c.filter(e => e.part === 'crown').length, 38); assert.equal(c.filter(e => e.part === 'pavilion').length, 32); assert.equal(new Set(c.map(x => x.id)).size, 70); });
test('8-fold brilliant has 33 crown and 24 pavilion definition planes', () => { assert.equal(generatePreset().planes.length, 33); assert.equal(generatePreset({ part: 'pavilion' }).planes.length, 24); });
test('exact inverse-transpose plane transform preserves incidence and inequality', () => { const p = { n: [.3, .4, .866025403784], d: .72 }, t = { translation: [.3, -.2, .7], rotation: [19, 27, -39], scale: [1.8, .63, 1.23] }, q = transformPlane(p, t); const a = [0, 0, p.d / p.n[2]], b = [.4, .2, (p.d - .12 - .08) / p.n[2]]; for (const v of [a, b])
    near(dot(q.n, transformPoint(v, t)), q.d); near(norm(q.n), 1); assert.ok(dot(q.n, transformPoint([0, 0, 0], t)) <= q.d); });
test('Z-only tangent-ratio remapping', () => { const c = generatePreset(), p = c.planes[0], q = transformPlane(p, { scale: [1, 1, 1.6] }), angle = x => Math.atan2(Math.hypot(x.n[0], x.n[1]), Math.abs(x.n[2])); near(Math.tan(angle(q)), Math.tan(angle(p)) * 1.6); });
test('invalid transforms rejected, never silently clamped', () => { assert.throws(() => normalizeTransform({ scale: [1, 0, 1] })); assert.throws(() => normalizeTransform({ translation: [0, NaN, 0] })); assert.throws(() => normalizeTransform({ rotation: [0, 0] })); });
test('component display interface cap is not exported as a cut', () => { const c = generatePreset(); assert.ok(componentPreview(c).some(p => p.role === 'interface')); assert.ok(instancePlanes(c).every(p => p.role !== 'interface')); });
test('keel generator produces a bottom line instead of a stretched point', () => { const c = generatePreset({ family: 'keel', part: 'pavilion', params: { keel: .5 } }), v = uniquePoints(componentPreview(c).flatMap(p => p.v)), z = Math.min(...v.map(x => x[2])), bottom = v.filter(x => Math.abs(x[2] - z) < 1e-7); assert.ok(bottom.length >= 2); near(Math.max(...bottom.map(x => x[0])) - Math.min(...bottom.map(x => x[0])), 1); });
test('negative Z translation cuts instead of adding material', () => { const c = generatePreset(), stock = prismSolid(); const a = cutSolid(stock, instancePlanes(c)), b = cutSolid(stock, instancePlanes(c, { translation: [0, 0, -.2] })); assert.ok(signedVolume(b) < signedVolume(a)); });
test('half-space operations are order independent and idempotent on convex stock', () => { const p = instancePlanes(generatePreset()), s = cubeSolid(3), a = cutSolid(s, p), b = cutSolid(s, p.slice().reverse()), c = cutSolid(a, p); near(signedVolume(a), signedVolume(b)); near(signedVolume(a), signedVolume(c)); });
test('ineffective planes stay in definition; stock polygons are not counted as cuts', () => { const s = cubeSolid(2), ps = [{ id: 'outside', n: [0, 0, 1], d: 3, isCut: true }], r = geometryStats(cutSolid(s, ps), ps); assert.equal(r.cutFacets, 0); assert.deepEqual(r.inactive, ['outside']); assert.equal(ps.length, 1); });
test('all-material-removed condition is detectable', () => { const out = cutSolid(cubeSolid(2), [{ n: [0, 0, 1], d: -2 }]); assert.equal(out.length, 0); assert.equal(geometryStats(out).volume, 0); });
test('fractional index compatibility checks every face, not merely main symmetry', () => { assert.equal(machineReport(instancePlanes(generatePreset()), 96).exact, true); assert.equal(machineReport(instancePlanes(generatePreset({ params: { symmetry: 9 } })), 96).exact, false); assert.equal(machineReport(instancePlanes(generatePreset({ params: { symmetry: 9 } })), 180).exact, true); assert.equal(machineReport(instancePlanes(generatePreset(), { rotation: [0, 0, 1] }), 96).exact, false); });
test('manual editing is immutable and detaches active recipe', () => { const c = generatePreset(), copy = clone(c), edited = editPlane(c, c.planes[0].id, { d: c.planes[0].d - .01 }); assert.deepEqual(c, copy); assert.equal(edited.recipe, undefined); assert.equal(edited.family, 'custom'); });
for (const [name, solid, expected] of [['L-shaped nonconvex', lSolid, 1.5], ['through-hole', ringSolid, 4], ['disconnected solids', disconnectedSolid, 1]])
    test(`${name}: half-depth cut has analytical volume ${expected}`, () => { const s = solid(), out = cutSolid(s, [halfPlane], { convex: false }); near(signedVolume(out), expected, 1e-6); assert.ok(out.flatMap(f => f.v).every(v => v[2] <= .500001)); });
test('through-hole cap does not fill the hole center', () => { const out = cutSolid(ringSolid(), [halfPlane], { convex: false }); const caps = out.filter(f => f.id === 'half'); assert.ok(caps.length > 1); const inside = (v, p) => { let sign = 0; for (let i = 0; i < v.length; i++) {
    const a = v[i], b = v[(i + 1) % v.length], z = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]);
    if (Math.abs(z) < 1e-8)
        continue;
    if (sign && Math.sign(z) !== sign)
        return false;
    sign = Math.sign(z);
} return true; }; assert.equal(caps.some(f => inside(f.v, [1.5, 1.5])), false); });
test('reference waist alignment and tilted rim warning', () => { const c = { component: generatePreset(), transform: normalizeTransform({ translation: [0, 0, .045] }) }, p = { component: generatePreset({ part: 'pavilion' }), transform: normalizeTransform({ translation: [0, 0, -.045] }) }; const r = interfaceReport(c, p); near(r.gap, .09); near(r.rimVertexDeviation, 0); assert.equal(interfaceReport({ ...c, transform: normalizeTransform({ rotation: [5, 0, 0] }) }, p).status, 'tilted'); });
test('section supports concave loops without replacing them by convex hull', () => { const segments = sectionSegments(ringSolid(), .5); assert.ok(segments.length >= 16); });
test('invalid recipe topology parameters return errors', () => { assert.throws(() => generatePreset({ params: { symmetry: 4.5 } })); assert.throws(() => generatePreset({ family: 'rose', part: 'pavilion' })); assert.throws(() => generatePreset({ family: 'rose', params: { symmetry: 32, layers: 8 } })); assert.throws(() => generatePreset({ family: 'step', params: { symmetry: 6, outline: 'emerald' } })); });
